	private function bad($message,$code='hr_lifecycle_invalid',$status=400){return new WP_Error($code,$message,array('status'=>$status));}
	private function table($key){return Stockland_DB::table($key);}
	private function owner(){return Stockland_Authority::can_approve_payroll();}
	private function date($v,$optional=true){if(($v===null||$v==='')&&$optional)return null;$v=sanitize_text_field((string)$v);if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$v,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))return false;return $v;}
	private function json_value($v,$name){$s=is_string($v)?$v:wp_json_encode($v);if(!is_string($s)||json_last_error()!==JSON_ERROR_NONE&&is_string($v))return $this->bad($name.' must be valid JSON.');json_decode($s,true);if(json_last_error()!==JSON_ERROR_NONE)return $this->bad($name.' must be valid JSON.');return $s;}
	private function sanitize_fields($payload,$fields){
		$out=array();$dates=array('target_start_date','issued_on','expires_on','start_date','end_date','probation_end','effective_from','effective_to','work_date','due_date','last_work_date','exit_date','scheduled_at','check_in','check_out','consent_at');
		$money=array('annual_salary_budget','other_cost_budget','annual_salary_min','annual_salary_max','annual_entitlement_days','max_carry_days','requested_days','opening_days','accrued_days','used_days','adjusted_days','closing_days','amount','taxable_amount','pensionable_amount','gross_total','taxable_total','exempt_total','tax_total','employee_pension_total','employer_pension_total','other_deductions_total','net_total','screening_score','total_score','rating');
		$ints=array('version_no','location_id','planned_headcount','headcount_slots','workforce_plan_id','position_id','openings','requisition_id','candidate_id','application_id','subject_id','employee_id','document_id','break_minutes','shift_id','ordinary_minutes','overtime_minutes','min_notice_days','leave_year','reviewer_id','source_period_id','rule_set_id');
		$json=array('terms_json','panel_json','scorecard_json','goals_json','components_json');
		foreach($fields as $f){if(!array_key_exists($f,$payload))continue;$v=$payload[$f];
			if(in_array($f,array('scheduled_at','check_in','check_out','consent_at'),true)){ $raw=sanitize_text_field((string)$v); if($raw==='')$v=null; else { $dt=DateTimeImmutable::createFromFormat('!Y-m-d\\TH:i',$raw); if(!$dt)return $this->bad('Invalid date/time value for '.$f.'.'); $v=$dt->format('Y-m-d H:i:s'); } } elseif(in_array($f,$dates,true)){$v=$this->date($v,true);if($v===false)return $this->bad('Invalid date/time value for '.$f.'.');}
			elseif(in_array($f,$json,true)){$v=$this->json_value($v,$f);if(is_wp_error($v))return $v;}
			elseif(in_array($f,$money,true)){try{$v=Stockland_Money::decimal(Stockland_Money::minor($v));if(Stockland_Money::minor($v)<0)return $this->bad($f.' cannot be negative.');}catch(Throwable $e){return $this->bad('Invalid numeric value for '.$f.'.');}}
			elseif(in_array($f,$ints,true)){if($v===null||$v==='')$v=null;else{$v=filter_var($v,FILTER_VALIDATE_INT);if($v===false||$v<0)return $this->bad('Invalid integer value for '.$f.'.');}}
			elseif($f==='email'){$v=sanitize_email($v);if(($payload[$f]??'')!==''&&!is_email($v))return $this->bad('Invalid email address.');}
			elseif(in_array($f,array('notes','reason','justification','decision_reason','correction_reason','source_note','decision_note'),true))$v=sanitize_textarea_field((string)$v);
			else $v=sanitize_text_field((string)$v);
			$out[$f]=$v;
		}return $out;
	}
	private function event($entity,$id,$event,$from,$to,$meta=array(),$rule_id=null,$version=null){return (bool)Stockland_HR_Lifecycle::write_event($entity,(int)$id,$event,$from,$to,$meta,$rule_id,$version);}
	private function list_table($key,$limit=300){global $wpdb;$table=$this->table($key);$rows=Stockland_DB::read_results($wpdb->prepare('SELECT * FROM %i ORDER BY id DESC LIMIT %d',$table,$limit),ARRAY_A);return is_array($rows)?$rows:array();}
	public function bootstrap(WP_REST_Request $req){
		global $wpdb;$pay=Stockland_Authority::can_view_payroll();
		$out=array('locations'=>array(),'employees'=>array(),'compensation'=>array(),'payroll'=>array(),'payroll_visible'=>$pay,'capabilities'=>array('hr_manage'=>Stockland_Authority::can_manage_hr(),'payroll_manage'=>Stockland_Authority::can_manage_payroll(),'payroll_approve'=>Stockland_Authority::can_approve_payroll()),'rule_sets'=>$this->list_table('hr_rule_sets'),'rule_components'=>$this->list_table('hr_rule_components'),'lists'=>array());
		$out['locations']=$this->list_table('locations',200);
		$out['employees']=$this->list_table('employees',500);
		$out['payroll']=$pay?$this->list_table('payroll_periods',120):array();
		if($pay){
			$out['compensation']=Stockland_DB::read_results($wpdb->prepare('SELECT c.id,c.employee_id,c.effective_from,c.base_salary,c.allowance_total,c.taxable_allowance_total,c.exempt_allowance_total,c.pensionable_salary,c.statutory_classification_status,c.statutory_classification_note,c.allowance_rule_version,c.approval_status,e.employee_id employee_code,e.full_name,e.branch_location_id FROM %i c INNER JOIN %i e ON e.id=c.employee_id ORDER BY c.effective_from DESC,c.id DESC LIMIT 500',$this->table('employee_compensation'),$this->table('employees')),ARRAY_A);
		}
		foreach($this->entities as $slug=>$cfg){$out['lists'][$slug]=$this->list_table($cfg['table']);}
		$out['lists']['exits']=$this->list_table('hr_exit_settlements');
		if(!$pay){$out['compensation']=array();$out['payroll']=array();$out['rule_sets']=array();$out['rule_components']=array();$out['lists']['adjustments']=array();}
		return rest_ensure_response($out);
	}
	public function create(WP_REST_Request $req){
		$entity=(string)$req['entity'];if(!isset($this->entities[$entity]))return $this->bad('Unknown lifecycle entity.');if($entity==='exits')return $this->bad('Create final settlements using the rule-backed calculation endpoint.','settlement_calculation_required',409);
		$cfg=$this->entities[$entity];$p=$req->get_json_params();$row=$this->sanitize_fields(is_array($p)?$p:array(),$cfg['fields']);if(is_wp_error($row))return $row;
		if(isset($row['location_id'])&&!empty($row['location_id'])&&!Stockland_Authority::can_access_location($row['location_id']))return $this->bad('Record location is outside the current user's authorized scope.','hr_location_forbidden',403);
		if(in_array($entity,array('documents','contracts'),true)&&empty($row['document_reference'])&&$entity==='documents')return $this->bad('Store a private vault reference; public file URLs are prohibited.');
		if($entity==='documents'&&!empty($row['document_reference'])&&preg_match('~^https?://~i',$row['document_reference']))return $this->bad('Public/external document URLs are prohibited. Use the approved private document-vault reference.');
		$required=array('workforce-plans'=>array('plan_code','fiscal_year','department','justification'),'positions'=>array('position_code','title','department'),'requisitions'=>array('requisition_code','position_id','justification'),'candidates'=>array('candidate_code','full_name'),'applications'=>array('requisition_id','candidate_id'),'interviews'=>array('application_id','interview_round'),'documents'=>array('subject_type','subject_id','document_type','document_reference'),'contracts'=>array('employee_id','contract_code','contract_type','start_date'),'onboarding'=>array('employee_id','task_code','task_title'),'shifts'=>array('shift_code','shift_name','start_time','end_time','effective_from'),'attendance'=>array('employee_id','work_date'),'leave-policies'=>array('policy_code','leave_type','effective_from'),'leave-balances'=>array('employee_id','leave_type','leave_year'),'leave-requests'=>array('employee_id','leave_type','start_date','end_date','requested_days'),'training'=>array('employee_id','training_code','title'),'performance'=>array('employee_id','review_period','reviewer_id'),'adjustments'=>array('employee_id','target_period_key','adjustment_type','amount','reason'));
		foreach($required[$entity]??array() as $f){if(!isset($row[$f])||$row[$f]==='')return $this->bad('Required field missing: '.$f.'.');}
		if($entity==='leave-requests'&&$row['end_date']<$row['start_date'])return $this->bad('Leave end date cannot be before start date.');
		if($entity==='attendance'&&isset($row['check_in'],$row['check_out'])&&$row['check_in']&&$row['check_out']&&$row['check_out']<$row['check_in'])return $this->bad('Attendance check-out must follow check-in.');
		if($entity==='candidates'&&empty($row['consent_at']))$row['consent_at']=current_time('mysql');
		$status_field=array('workforce-plans'=>'status','positions'=>'status','requisitions'=>'status','candidates'=>'status','applications'=>'stage','interviews'=>'recommendation','documents'=>'status','contracts'=>'status','onboarding'=>'status','shifts'=>'status','attendance'=>'status','leave-policies'=>'status','leave-requests'=>'status','training'=>'status','performance'=>'outcome','adjustments'=>'status');
		$sf=$status_field[$entity]??null;if($sf&&!array_key_exists($sf,$row))$row[$sf]=in_array($entity,array('applications'),true)?'APPLIED':'DRAFT';
		$row['created_by']=get_current_user_id();if($entity==='attendance'){$row['submitted_by']=get_current_user_id();$row['status']='SUBMITTED';}
		if(in_array($entity,array('workforce-plans','positions','requisitions','contracts','leave-policies','shifts','adjustments'),true))$row['status']='DRAFT';
		if($entity==='leave-requests')$row['status']='SUBMITTED';
		$payload_for_audit=$row;foreach(array('full_name','email','phone','terms_json','panel_json','scorecard_json','goals_json','notes') as $sensitive){if(isset($payload_for_audit[$sensitive]))$payload_for_audit[$sensitive]='[REDACTED]';}
		if(Stockland_DB::execute_query('START TRANSACTION')===false)return $this->bad('Could not start HR record transaction.','hr_transaction_failed',500);
		if(Stockland_DB::insert_record($this->table($cfg['table']),$row)===false){Stockland_DB::execute_query('ROLLBACK');return $this->bad('Record could not be saved. Check fields and schema readiness.','hr_lifecycle_insert_failed',409);}
		global $wpdb;$id=(int)$wpdb->insert_id;
		if(!$this->event($entity,$id,'CREATED',null,$row[$sf]??'DRAFT',array('fields'=>array_keys($row),'snapshot_sha256'=>hash('sha256',wp_json_encode($payload_for_audit))))){Stockland_DB::execute_query('ROLLBACK');return $this->bad('Audit event failed; record creation was rolled back.','hr_audit_event_failed',500);}
		if(Stockland_DB::execute_query('COMMIT')===false){Stockland_DB::execute_query('ROLLBACK');return $this->bad('HR record transaction could not commit.','hr_transaction_failed',500);}
		return rest_ensure_response(array('id'=>$id,'entity'=>$entity,'status'=>$row[$sf]??'DRAFT','message'=>'Saved. Workflow approvals remain separate.'));
	}
	public function decision(WP_REST_Request $req){
		$entity=(string)$req['entity'];$id=(int)$req['id'];$p=$req->get_json_params();$decision=strtoupper(sanitize_key((string)($p['decision']??'')));$note=sanitize_textarea_field((string)($p['note']??''));if(!isset($this->entities[$entity])&&$entity!=='exits')return $this->bad('Unknown lifecycle entity.');
		if(!in_array($decision,array('SUBMIT','APPROVE','REJECT','COMPLETE','CONFIRM','PAY'),true))return $this->bad('Unsupported state transition.');
		if($decision==='APPROVE'&&!$this->owner()&&in_array($entity,array('workforce-plans','positions','requisitions','contracts','leave-policies','adjustments','exits'),true))return $this->bad('Owner approval is required for this financial/employment commitment.','forbidden',403);
		if($entity==='exits'&&in_array($decision,array('APPROVE','PAY'),true))return $this->bad('Final settlement approval/payment uses the dedicated rule-backed settlement handler.','settlement_handler_required',409);
		$cfg=$entity==='exits'?array('table'=>'hr_exit_settlements','status'=>'status'):$this->entities[$entity];$table=$this->table($cfg['table']);$statusCol=$entity==='performance'?'outcome':($entity==='applications'?'stage':'status');
		global $wpdb;if(Stockland_DB::execute_query('START TRANSACTION')===false)return $this->bad('Could not start workflow transaction.','hr_transaction_failed',500);
		try{
			$row=Stockland_DB::read_row($wpdb->prepare('SELECT * FROM %i WHERE id=%d FOR UPDATE',$table,$id),ARRAY_A);if(!$row)throw new RuntimeException('Record does not exist.');
			$from=(string)($row[$statusCol]??'DRAFT');
			$map=array('SUBMIT'=>array('DRAFT'=>'SUBMITTED','CALCULATED'=>'SUBMITTED'),'APPROVE'=>array('SUBMITTED'=>'APPROVED','PENDING_REVIEW'=>'APPROVED','CALCULATED'=>'APPROVED'),'REJECT'=>array('SUBMITTED'=>'REJECTED','DRAFT'=>'REJECTED','PENDING_REVIEW'=>'REJECTED'),'COMPLETE'=>array('OPEN'=>'COMPLETE','PLANNED'=>'COMPLETE','IN_PROGRESS'=>'COMPLETE'),'CONFIRM'=>array('OFFERED'=>'CONFIRMED','PROBATION'=>'CONFIRMED'),'PAY'=>array('APPROVED'=>'PAID'));
			$to=$map[$decision][$from]??null;if(!$to)throw new RuntimeException('Invalid transition '.$from.' → '.$decision.'.');
			if(in_array($decision,array('APPROVE','PAY','CONFIRM'),true)&&$note==='')$note='Approved by authorized reviewer.';
			$data=array($statusCol=>$to);if(in_array($decision,array('APPROVE','REJECT'),true)){$data['approved_by']=get_current_user_id();$data['approved_at']=current_time('mysql');if(isset($row['decision_note']))$data['decision_note']=$note;}
			if($entity==='attendance'&&$decision==='APPROVE'){$data['approved_by']=get_current_user_id();$data['approved_at']=current_time('mysql');}
			if($entity==='leave-requests'&&in_array($decision,array('APPROVE','REJECT'),true)){$data['decided_by']=get_current_user_id();$data['decided_at']=current_time('mysql');$data['decision_note']=$note;}
			if(Stockland_DB::update_record($table,$data,array('id'=>$id))===false)throw new RuntimeException('Could not persist workflow decision.');
			if(!$this->event($entity,$id,$decision,$from,$to,array('note'=>$note,'actor_role'=>Stockland_Authority::role())))throw new RuntimeException('Audit event failed; transition rolled back.');
			if(Stockland_DB::execute_query('COMMIT')===false)throw new RuntimeException('Workflow commit failed.');
			return rest_ensure_response(array('id'=>$id,'status'=>$to));
		}catch(Throwable $e){Stockland_DB::execute_query('ROLLBACK');return $this->bad($e->getMessage(),'hr_workflow_transition_failed',409);}
	}
	public function create_rule(WP_REST_Request $req){
		$p=$req->get_json_params();$type=strtoupper(sanitize_key((string)($p['rule_type']??'')));$allowed=array('PAYROLL','ALLOWANCE','LEAVE','OVERTIME','FINAL_SETTLEMENT');$version=sanitize_text_field((string)($p['version_label']??''));$from=$this->date($p['effective_from']??null,false);$to=$this->date($p['effective_to']??null,true);$title=sanitize_text_field((string)($p['source_title']??''));$url=esc_url_raw((string)($p['source_url']??''));$clause=sanitize_text_field((string)($p['source_clause']??''));$sha=strtolower(sanitize_text_field((string)($p['source_sha256']??'')));$rules=$this->json_value($p['rules_json']??array(),'rules_json');if(is_wp_error($rules))return $rules;
		if(!in_array($type,$allowed,true)||$version===''||$from===false||$to===false||($to&&$to<$from)||$title===''||!preg_match('~^https://~i',$url)||$clause===''||!preg_match('/^[a-f0-9]{64}$/',$sha))return $this->bad('Rule type, version, effective dates, official HTTPS source, clause and source SHA-256 are mandatory.');
		if(Stockland_DB::insert_record($this->table('hr_rule_sets'),array('rule_code'=>sanitize_key((string)($p['rule_code']??$type)),'rule_type'=>$type,'version_label'=>$version,'jurisdiction'=>sanitize_text_field((string)($p['jurisdiction']??'ETHIOPIA-FEDERAL')),'effective_from'=>$from,'effective_to'=>$to,'source_title'=>$title,'source_url'=>$url,'source_clause'=>$clause,'source_sha256'=>$sha,'source_publication_date'=>$this->date($p['source_publication_date']??null,true),'review_status'=>'DRAFT','rules_json'=>$rules,'created_by'=>get_current_user_id()))===false)return $this->bad('Rule-set insert failed. The version or source identifier may already exist.','hr_rule_create_failed',409);
		global $wpdb;$id=(int)$wpdb->insert_id;$components=$p['components']??array();if(!is_array($components))return $this->bad('Rule components must be a list.');
		if($type==='ALLOWANCE'&&!$components)return $this->bad('An allowance rule requires explicit per-category classification components.');
		foreach($components as $c){if(!is_array($c)||empty($c['category'])||empty($c['source_clause']))return $this->bad('Each allowance rule component requires category and source clause.');$t=strtoupper(sanitize_key((string)($c['tax_treatment']??'TAXABLE')));if(!in_array($t,array('TAXABLE','EXEMPT_CAP','EXEMPT_FULL'),true))return $this->bad('Unknown tax treatment.');$cap=isset($c['exemption_cap'])?Stockland_Money::decimal(Stockland_Money::minor($c['exemption_cap'])):null;if($t==='EXEMPT_CAP'&&($cap===null||Stockland_Money::minor($cap)<0))return $this->bad('A non-negative exemption cap is required for EXEMPT_CAP.');if(Stockland_DB::insert_record($this->table('hr_rule_components'),array('rule_set_id'=>$id,'category'=>strtoupper(sanitize_key((string)$c['category'])),'tax_treatment'=>$t,'exemption_cap'=>$cap,'pensionable_treatment'=>strtoupper(sanitize_key((string)($c['pensionable_treatment']??'SALARY_ONLY'))),'pensionable_cap'=>isset($c['pensionable_cap'])?Stockland_Money::decimal(Stockland_Money::minor($c['pensionable_cap'])):null,'source_clause'=>sanitize_text_field((string)$c['source_clause']),'source_note'=>sanitize_textarea_field((string)($c['source_note']??'')),'created_by'=>get_current_user_id()))===false)return $this->bad('Could not save rule component.');}
		$this->event('rule-set',$id,'RULE_DRAFT',null,'DRAFT',array('type'=>$type,'version'=>$version,'source_sha256'=>$sha));return rest_ensure_response(array('id'=>$id,'review_status'=>'DRAFT','message'=>'Draft only. Owner cannot approve a rule created by the same account; use independent preparation and legal review.'));
	}
	public function approve_rule(WP_REST_Request $req){
